import React, { useState, useMemo } from "react";
import { FaInstagram, FaFacebookF, FaTwitter } from "react-icons/fa";
import { useCart } from "react-use-cart";

import {
  Gem,
  Sparkles,
  CircleDot,
  Star,
  Link2,
  Watch,
  ShoppingBag,
} from "lucide-react";

import { Link } from "react-router-dom";

/* ============================================================
   FONTS
   ============================================================ */

function Cart() {
    const {items,  updateItemQuantity, removeItem,totalitems,totalUniqueItems, cartTotal, isEmpty, emptyCart}
     = useCart();
 function PageCollection() {
   const [selectedCategory, setSelectedCategory] = useState("All");
 
   const filteredProducts = useMemo(() => {
     if (selectedCategory === "All") {
       return PRODUCTS;
     }
 
     return PRODUCTS.filter(
       (product) => product.category === selectedCategory
     );
   }, [selectedCategory]);
 
   return (
     <>
       <style>{fontImport}</style>
 
       <main className="lux-page">
 
         {/* ====================================================
             HERO
         ==================================================== */}
 
         <section className="lux-collections-hero">
           <div className="lux-collections-hero-content">
 
             <span className="lux-hero-eyebrow">
               MAISON &amp; LUXE
             </span>
 
             <h1>
               Our Collections
             </h1>
 
             <p>
               Discover timeless pieces crafted to complement
               every moment and every story.
             </p>
 
           </div>
         </section>
 
         {/* ====================================================
             CATEGORIES
         ==================================================== */}
 
         <section className="lux-category-section">
 
           <div className="lux-category-list">
 
             {CATEGORIES.map((category) => {
               const Icon = category.icon;
 
               const isActive =
                 selectedCategory === category.id;
 
               return (
                 <button
                   key={category.id}
                   type="button"
                   className={
                     isActive
                       ? "lux-category-btn active"
                       : "lux-category-btn"
                   }
                   onClick={() =>
                     setSelectedCategory(category.id)
                   }
                 >
                   <Icon
                     size={18}
                     strokeWidth={1.4}
                   />
 
                   <span>
                     {category.label}
                   </span>
                 </button>
               );
             })}
 
           </div>
 
         </section>
 
         {/* ====================================================
             PRODUCTS
         ==================================================== */}
 
         <section className="lux-products-section">
 
           <div className="lux-products-header">
 
             <div>
               <span className="lux-products-eyebrow">
                 COLLECTION
               </span>
 
               <h2>
                 {selectedCategory === "All"
                   ? "All Pieces"
                   : selectedCategory}
               </h2>
             </div>
 
             <span className="lux-products-count">
               {filteredProducts.length}{" "}
               {filteredProducts.length === 1
                 ? "piece"
                 : "pieces"}
             </span>
 
           </div>
 
           {filteredProducts.length > 0 ? (
 
             <div className="lux-products-grid">
 
               {filteredProducts.map((product) => (
                 <ProductCard
                   key={product.id}
                   product={product}
                 />
               ))}
 
             </div>
 
           ) : (
 
             <div className="lux-empty-products">
 
               <Sparkles
                 size={42}
                 strokeWidth={1}
               />
 
               <h3>
                 No products found
               </h3>
 
               <p>
                 There are currently no products in this
                 collection.
               </p>
 
               <button
                 type="button"
                 className="lux-btn lux-btn-solid"
                 onClick={() =>
                   setSelectedCategory("All")
                 }
               >
                 View All Products
               </button>
 
             </div>
 
           )}
 
         </section>
 
         {/* ====================================================
             FOOTER
         ==================================================== */}
 
         <PlaceholderFooter />
 
       </main>
     </>
   );
 }}
/* ============================================================
   ALL CART
   ============================================================ */

function AllCart() {

  const [selectedCategory, setSelectedCategory] =
    useState("All");

  const filteredProducts = useMemo(() => {

    if (selectedCategory === "All") {
      return PRODUCTS;
    }

    return PRODUCTS.filter(
      (product) =>
        product.category === selectedCategory
    );

  }, [selectedCategory]);

  return (
    <>
      <style>
        {fontImport}
      </style>

      <main className="lux-page">

        {/* ====================================================
            HERO
        ==================================================== */}

        <section className="lux-collections-hero">

          <div className="lux-collections-hero-content">

            <span className="lux-hero-eyebrow">
              MAISON &amp; LUXE
            </span>

            <h1>
              All Products
            </h1>

            <p>
              Discover timeless pieces crafted to
              complement every moment and every story.
            </p>

          </div>

        </section>

        {/* ====================================================
            CATEGORIES
        ==================================================== */}

        <section className="lux-category-section">

          <div className="lux-category-list">

            {CATEGORIES.map((category) => {

              const Icon = category.icon;

              const isActive =
                selectedCategory === category.id;

              return (
                <button
                  key={category.id}
                  type="button"
                  className={
                    isActive
                      ? "lux-category-btn active"
                      : "lux-category-btn"
                  }
                  onClick={() =>
                    setSelectedCategory(
                      category.id
                    )
                  }
                >

                  <Icon
                    size={18}
                    strokeWidth={1.4}
                  />

                  <span>
                    {category.label}
                  </span>

                </button>
              );

            })}

          </div>

        </section>

        {/* ====================================================
            PRODUCTS
        ==================================================== */}

        <section className="lux-products-section">

          <div className="lux-products-header">

            <div>

              <span className="lux-products-eyebrow">
                COLLECTION
              </span>

              <h2>
                {selectedCategory === "All"
                  ? "All Pieces"
                  : selectedCategory}
              </h2>

            </div>

            <span className="lux-products-count">

              {filteredProducts.length}{" "}

              {filteredProducts.length === 1
                ? "piece"
                : "pieces"}

            </span>

          </div>

          {filteredProducts.length > 0 ? (

            <div className="lux-products-grid">

              {filteredProducts.map((product) => (

                <ProductCard
                  key={product.id}
                  product={product}
                />

              ))}

            </div>

          ) : (

            <div className="lux-empty-products">

              <Sparkles
                size={42}
                strokeWidth={1}
              />

              <h3>
                No products found
              </h3>

              <p>
                There are currently no products
                in this collection.
              </p>

              <button
                type="button"
                className="lux-btn lux-btn-solid"
                onClick={() =>
                  setSelectedCategory("All")
                }
              >
                View All Products
              </button>

            </div>

          )}

        </section>

        {/* ====================================================
            FOOTER
        ==================================================== */}

        <PlaceholderFooter />

      </main>
    </>
  );
}

/* ============================================================
   EXPORT
   ============================================================ */

export default AllCart;
